57:                     }
58:                 }
59:             }
60:             sessionCounters = sessionRepository.sessionCounters
61:             dynamicDeviceInfo = deviceInfoRepository.dynamicDeviceInfo
62:             val piiData = deviceInfoRepository.piiData
