64:             campaignState = campaignRepository.getCampaignState()
65:             tcfRepository.tcfString?.let { tcf = it.toByteStringUtf8() }
66:             this.scarSignalsCollected = scarSignalsCollected
67:             this.offerwallEnabled = offerwallManager.isConnected()
68:             // Specific fields
69:             if (sToken.isEmpty) {
70:                 if (sessionRepository.gameId?.isNotEmpty() == true) {
71:                     // Init Token
72:                     initializationData = getInitializationData()
73:                 } else {
