82:             }
83:             testDataInfo()?.let { testData = it }
84:             tokenCounters = tokenCounters {
85:                 seq = currentTokenCounters.seq
86:                 wins = currentTokenCounters.wins
87:                 starts = currentTokenCounters.starts
88:             }
89:         }
